BEGIN;

-- calc が {"steps":[...],"formula":"..."} というオブジェクトで入っていた25問を修正。
-- ExplanationData.calc は string 型必須（src/features/quiz/lib/types.ts, rich-explanation.tsx で
-- {data.calc} を直接描画するため、オブジェクトだとReactが例外を投げ全画面クラッシュする）。
-- steps を改行結合し、末尾に formula を続けた1本の文字列に変換する。
UPDATE public.questions q
SET explanation_data = jsonb_set(q.explanation_data, '{calc}', to_jsonb(v.value))
FROM jsonb_each_text('{"e-shikaku-b-q43": "問題: 3つのデータでx=(1,2,3)、y=(2,1,3)とする\nステップ1: 平均を求める。x̄=(1+2+3)÷3=2、ȳ=(2+1+3)÷3=2\nステップ2: 平均との差(偏差)を求める。xの偏差=(-1,0,1)、yの偏差=(0,-1,1)\nステップ3: 分散を求める(偏差を2乗して平均)。Var(x)=((-1)²+0²+1²)÷3=2/3≈0.67、Var(y)=(0²+(-1)²+1²)÷3=2/3≈0.67\nステップ4: 共分散を求める(偏差同士の積を平均)。Cov(x,y)=((-1)×0+0×(-1)+1×1)÷3=1/3≈0.33\n答え: 対角成分(分散)は約0.67、非対角成分(共分散)は約0.33\n\nVar(x)=Σ(xᵢ-x̄)²÷n, Cov(x,y)=Σ(xᵢ-x̄)(yᵢ-ȳ)÷n", "e-shikaku-b-q45": "問題: σ=8、N=4のときとN=16のときのSE=σ/√Nを求める\nステップ1: N=4のとき、√4=2\nステップ2: SE=8÷2=4\nステップ3: N=16のとき、√16=4\nステップ4: SE=8÷4=2\n答え: N=4でSEは4、N=16でSEは2(標本サイズを4倍にするとSEは半分)\n\nSE = σ ÷ √N", "e-shikaku-b-q47": "問題: 生産割合A=0.40, B=0.35, C=0.25 / 不良率A=0.02, B=0.03, C=0.05\nステップ1: ラインAの寄与 = 0.40 × 0.02 = 0.008\nステップ2: ラインBの寄与 = 0.35 × 0.03 = 0.0105\nステップ3: ラインCの寄与 = 0.25 × 0.05 = 0.0125\nステップ4: 全部足す = 0.008 + 0.0105 + 0.0125 = 0.031\n答え: 工場全体の不良率は約3.1%\n\n全体の不良率 = Σ(各ラインの割合 × 各ラインの不良率)", "e-shikaku-b-q48": "問題: P(X=0,Y=0)=0.5, P(X=1,Y=1)=0.5, 残り2項は0。P(X=0)=P(X=1)=P(Y=0)=P(Y=1)=0.5\nステップ1: (X=0,Y=0)の項 : P(x,y)/(P(x)P(y)) = 0.5/(0.5×0.5) = 0.5/0.25 = 2、log2(2) = 1\nステップ2: その項の寄与 = 0.5 × 1 = 0.5\nステップ3: (X=1,Y=1)の項も同じ計算で寄与 = 0.5\nステップ4: P=0の2項は0として無視し、0.5+0.5を合計する\n答え: I(X;Y) = 0.5 + 0.5 = 1(ビット)\n\nI(X;Y) = Σ P(x,y) log2(P(x,y) ÷ (P(x)P(y)))", "e-shikaku-b-q49": "問題: v = (3, -4, 0, 2)\nステップ1: 0でない成分を数える。3, -4, 2の3個が0でない → L0ノルム = 3\nステップ2: 各成分の絶対値を並べる。|3|=3, |-4|=4, |0|=0, |2|=2\nステップ3: そのうち最大のものを選ぶ。3, 4, 0, 2の中で最大は4\n答え: L0ノルム=3、L∞ノルム=4\n\nL0ノルム = #{i : vᵢ≠0}, L∞ノルム = max(|v₁|,|v₂|,...,|vₙ|)", "e-shikaku-b-q50": "問題: A は5行3列なので m=5, n=3\nステップ1: U は行(m個)に対応する正方行列 → 5×5\nステップ2: Σ は A とサイズをそろえる行列(対角成分だけが特異値) → 5×3\nステップ3: Vᵀ は列(n個)に対応する正方行列 → 3×3\n答え: U=5×5, Σ=5×3, Vᵀ=3×3\n\nA(m×n) = U(m×m) Σ(m×n) Vᵀ(n×n)", "e-shikaku-b-q53": "問題: H(p) = -p log2(p) - (1-p) log2(1-p) をp=0.5とp=0.1で計算する\nステップ1: p=0.5のとき。-0.5×log2(0.5) - 0.5×log2(0.5) = -0.5×(-1) - 0.5×(-1) = 0.5+0.5 = 1\nステップ2: p=0.1のとき、-p log2(p)の項。-0.1×log2(0.1) ≈ -0.1×(-3.32) = 0.332\nステップ3: p=0.1のとき、-(1-p) log2(1-p)の項。-0.9×log2(0.9) ≈ -0.9×(-0.152) = 0.137\nステップ4: 2つの項を足す。0.332 + 0.137 ≈ 0.469\n答え: H(0.5)=1(ビット)、H(0.1)は約0.47(ビット)で、p=0.5のほうが大きい\n\nH(p) = -p log2(p) - (1-p) log2(1-p)", "e-shikaku-b-q54": "問題: 1つのデータで正解ラベルy=1、モデルの予測確率p=0.8とする\nステップ1: このデータの尤度はモデルの予測確率そのまま。L = 0.8\nステップ2: 対数尤度を求める。log(0.8) ≈ -0.223\nステップ3: 符号を反転する(負の対数尤度)。-log(0.8) ≈ 0.223\nステップ4: クロスエントロピー損失 -y log(p) - (1-y) log(1-p) にy=1, p=0.8を入れると、後半の項は0になり -log(0.8) ≈ 0.223 と一致する\n答え: 負の対数尤度とクロスエントロピー損失は同じ0.223になる(符号を反転させた対数尤度=クロスエントロピー)\n\nクロスエントロピー損失 = -対数尤度 = -Σ [y log(p) + (1-y) log(1-p)]", "e-shikaku-q53": "問題: A=[[3,4],[2,5]]の行列式を求める\nステップ1: 公式|A|=ad-bcを使う。a=3,b=4,c=2,d=5\nステップ2: ad=3×5=15\nステップ3: bc=4×2=8\nステップ4: 15-8=7\n答え: 7(0ではないのでAは正則行列)\n\n|A| = ad - bc = 3×5 - 4×2 = 15 - 8 = 7", "e-shikaku-q54": "問題: B=[[2,0],[0,4]]の逆行列を求める\nステップ1: 対角行列の逆行列は、各対角成分の逆数を取るだけでよい\nステップ2: 1つ目の対角成分2の逆数は1/2\nステップ3: 2つ目の対角成分4の逆数は1/4\n答え: [[1/2,0],[0,1/4]]\n\nB⁻¹ = [[1/2,0],[0,1/4]] (B×B⁻¹=単位行列Iになることで確認できる)", "e-shikaku-q55": "問題: C=[[1,2,3],[4,5,6],[7,8,9]]の転置行列Cᵀを求める\nステップ1: 転置は元のi行j列の要素を、j行i列に置き直す操作\nステップ2: 1行目[1,2,3]は、転置後は1列目[1,2,3]になる\nステップ3: 2行目[4,5,6]は、転置後は2列目[4,5,6]になる\nステップ4: 3行目[7,8,9]は、転置後は3列目[7,8,9]になる\n答え: [[1,4,7],[2,5,8],[3,6,9]]\n\n(Cᵀ)のj行i列 = Cのi行j列", "e-shikaku-q56": "問題: μ=0,σ=1のとき、f(0)の値を求める\nステップ1: 指数部分を計算する。-(x-μ)²/(2σ²) = -(0-0)²/(2×1) = 0\nステップ2: exp(0)=1(何乗もしていないので1のまま)\nステップ3: 残りの部分を計算する。1/√(2πσ²) = 1/√(2π×1) = 1/√(2π)\nステップ4: √(2π)≈2.507なので、1÷2.507≈0.399\n答え: 約0.399\n\nf(0) = 1/√(2π×1²) × exp(0) = 1/√(2π) ≈ 0.399", "e-shikaku-q57": "問題: 区間[2,10]の一様分布の期待値と分散を求める\nステップ1: 期待値は区間の中点。E[X]=(a+b)/2=(2+10)/2=6\nステップ2: 分散の公式(b-a)²/12を使うため、まずb-aを計算する。10-2=8\nステップ3: 8を2乗する。8²=64\nステップ4: 64を12で割る。64÷12=16/3≈5.33\n答え: E[X]=6, V[X]=16/3(≈5.33)\n\nE[X]=(a+b)/2=6, V[X]=(b-a)²/12=64/12=16/3", "e-shikaku-q58": "問題: 1000個のうち不良品は5%=50個、良品は950個とする\nステップ1: 不良品50個のうち95%が正しく不良と判定される。50×0.95=47.5個\nステップ2: 良品950個のうち2%が誤って不良と判定される。950×0.02=19個\nステップ3: 不良と判定された部品の合計は47.5+19=66.5個\nステップ4: そのうち本当に不良なのは47.5個なので、47.5÷66.5≈0.714\n答え: 約71%\n\nP(不良|不良判定) = 47.5 ÷ (47.5+19) = 47.5/66.5 ≈ 0.714 → 約71%", "e-shikaku-q59": "問題: (1,2),(2,4),(3,5),(4,4),(5,5)の5組データの共分散を求める(nで割る)\nステップ1: Xの平均は(1+2+3+4+5)/5=3、Yの平均は(2+4+5+4+5)/5=4\nステップ2: 各組の(X-平均)×(Y-平均)を計算する。(-2)×(-2)=4, (-1)×0=0, 0×1=0, 1×0=0, 2×1=2\nステップ3: これらを合計する。4+0+0+0+2=6\nステップ4: データ数5で割る。6÷5=1.2\n答え: 1.2\n\nCov(X,Y) = (1/n)Σ(x_i-x̄)(y_i-ȳ) = 6/5 = 1.2", "e-shikaku-q60": "問題: Cov(X,Y)=6, σx=3, σy=4から相関係数rを求める\nステップ1: 相関係数は共分散を標準偏差の積で割って求める\nステップ2: 標準偏差の積を計算する。σx×σy=3×4=12\nステップ3: 共分散を標準偏差の積で割る。6÷12=0.5\n答え: 0.5\n\nr = Cov(X,Y) / (σx × σy) = 6/12 = 0.5", "e-shikaku-q61": "問題: 確率p=0.25の事象の自己情報量を求める(単位: ビット)\nステップ1: 自己情報量は-log2(p)で計算する\nステップ2: p=0.25=1/4=2の-2乗(2^-2)と書き直せる\nステップ3: log2(2^-2)=-2なので、-log2(0.25)=-(-2)=2\n答え: 2ビット\n\nI(x) = -log2(p) = -log2(0.25) = -log2(2^-2) = 2 [ビット]", "e-shikaku-q62": "問題: データ2,4,6,8の不偏分散を求める\nステップ1: 平均を求める。(2+4+6+8)/4=5\nステップ2: 各データと平均の差を2乗する。(2-5)²=9, (4-5)²=1, (6-5)²=1, (8-5)²=9\nステップ3: 2乗した値を合計する(偏差平方和)。9+1+1+9=20\nステップ4: データ数4から1を引いた3で割る。20÷3≈6.67\n答え: 約6.67\n\ns² = Σ(x_i-x̄)² / (n-1) = 20/3 ≈ 6.67", "e-shikaku-q63": "問題: ベクトルa=(1,2)とb=(2,1)のコサイン類似度を求める\nステップ1: 内積を計算する。a・b=1×2+2×1=2+2=4\nステップ2: aのL2ノルム(長さ)を計算する。|a|=√(1²+2²)=√5\nステップ3: bのL2ノルムを計算する。|b|=√(2²+1²)=√5\nステップ4: 内積をノルムの積で割る。4÷(√5×√5)=4÷5=0.8\n答え: 0.8\n\ncos θ = (a・b) / (|a||b|) = 4 / (√5×√5) = 4/5 = 0.8", "e-shikaku-q64": "問題: V[X]=4のとき、Y=3X+5の分散V[Y]を求める\nステップ1: 分散の性質V[aX+b]=a²V[X]を使う。定数bを足してもばらつきは変わらない\nステップ2: 係数a=3を2乗する。3²=9\nステップ3: 9×4=36\n答え: 36\n\nV[aX+b] = a²V[X] = 3²×4 = 36", "g-kentei-k-q36": "問題: 上の行が2と3、下の行が1と4に並んだ2×2の行列の行列式を求める\nステップ1: 2×2の行列式は「左上×右下 − 右上×左下」で計算する\nステップ2: 左上×右下を計算する。2×4=8\nステップ3: 右上×左下を計算する。3×1=3\nステップ4: 2つの結果を引き算する。8−3=5\n答え: 行列式は5\n\n行列式 = (左上×右下) − (右上×左下) = (2×4) − (3×1) = 8 − 3 = 5", "g-kentei-k-q37": "問題: 対角線上に2と4が並んだ行列Aに対して、対角線上に0.5と0.25が並んだ行列Bを掛けたとき、単位行列になるか確かめる\nステップ1: 行列の左上同士を掛ける。2×0.5=1\nステップ2: 行列の右下同士を掛ける。4×0.25=1\nステップ3: 対角線以外の成分はもともと0なので、掛け算の結果も0のまま\n答え: 対角線が1、他が0の行列になった。これは単位行列そのものなので、BはAの逆行列である\n\nA × B = [[2×0.5, 0], [0, 4×0.25]] = [[1,0],[0,1]] = 単位行列", "g-kentei-k-q41": "問題: 2行3列の行列と、3行4列の行列を掛け算できるか調べ、できるなら結果が何行何列になるか求める\nステップ1: 前の行列の列数（3）と、後ろの行列の行数（3）を比べる\nステップ2: 3と3で数が一致しているので、この2つの行列は掛け算できる\nステップ3: 結果の行数は、前の行列の行数である2\nステップ4: 結果の列数は、後ろの行列の列数である4\n答え: 2行4列の行列になる\n\n2行3列 × 3行4列 → 3=3（一致）なので掛け算でき、結果は2行4列", "g-kentei-k-q42": "問題: 成分が3と4のベクトル(3,4)を正規化し、単位ベクトルを求める\nステップ1: まずベクトルの長さ（ノルム）を求める。各成分を2乗して足す。3×3+4×4=9+16=25\nステップ2: 25を、掛けると25になる数に戻す。5×5=25なので、長さは5\nステップ3: 各成分を、求めた長さ5で割る。3÷5=0.6、4÷5=0.8\n答え: 単位ベクトルは(0.6, 0.8)。向きは(3,4)と同じで、長さはちょうど1になっている\n\n単位ベクトル = (3,4) ÷ 長さ(3,4) = (3,4) ÷ 5 = (0.6, 0.8)", "g-kentei-k-q46": "問題: 標準偏差が20のとき、標本の人数を100人から400人に増やすと標準誤差はどう変わるか\nステップ1: 人数100人のときの標準誤差を求める。100の√(ルート、2乗すると元の数に戻る数)は10(10×10=100だから)。20 ÷ 10 = 2\nステップ2: 人数400人のときの標準誤差を求める。400の√は20(20×20=400だから)。20 ÷ 20 = 1\n答え: 人数を100人から400人(4倍)に増やすと、標準誤差は2から1へと半分になる\n\n標準誤差 = 標準偏差 ÷ √n（nは標本の人数、√は「2乗すると元の数に戻る数」を求める計算）"}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.explanation_data IS NOT NULL;

COMMIT;
